1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import { capFor, payoutForDamages, type Damage } from "./coverage.js";
7	
8	export type { Customer, KnownItemType } from "./pricing.js";
9	export type { Damage } from "./coverage.js";
10	
11	export interface Scenario {
12	  customer: Customer;
13	  steps: Step[];
14	}
15	
16	export interface QuoteStep {
17	  op: "quote";
18	  items: Item[];
19	}
20	
21	export interface ClaimStep {
22	  op: "claim";
23	  policy: number;
24	  incident: { cause: string; damages: Damage[] };
25	}
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export interface ScenarioResults {
30	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
31	}
32	
33	// What earlier steps have established by the time a later step is priced.
34	// Steps are not independent: a quote is a follow-up contract when the customer
35	// already took a quote earlier in the same scenario. Folding this forward —
36	// rather than re-deriving it from the step prefix — is what lets a step read
37	// the state its predecessors left behind.
38	interface Policy {
39	  remainingCap: number;
40	}
41	
42	interface ScenarioState {
43	  hasQuoted: boolean;
44	  // Keyed by the step index of the quote that created the policy, which is
45	  // how a later claim step refers to it.
46	  policies: Map<number, Policy>;
47	}
48	
49	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
50	
51	type StepOutcome = ScenarioResults["results"][number];
52	
53	interface StepRun {
54	  outcome: StepOutcome;
55	  state: ScenarioState;
56	}
57	
58	// Every policy a step establishes is recorded the same way, so both handlers
59	// go through here rather than each rebuilding the map.
60	const withPolicy = (
61	  state: ScenarioState,
62	  index: number,
63	  policy: Policy,
64	): ScenarioState => ({
65	  ...state,
66	  policies: new Map(state.policies).set(index, policy),
67	});
68	
69	const runQuote = (
70	  { items }: QuoteStep,
71	  customer: Customer,
72	  state: ScenarioState,
73	  index: number,
74	): StepRun => ({
75	  outcome: {
76	    premium: premiumFor(items, {
77	      customer,
78	      isFollowUpContract: state.hasQuoted,
79	    }),
80	  },
81	  state: withPolicy({ ...state, hasQuoted: true }, index, {
82	    remainingCap: capFor(items),
83	  }),
84	});
85	
86	const runClaim = (
87	  { policy: policyIndex, incident }: ClaimStep,
88	  state: ScenarioState,
89	): StepRun => {
90	  // A claim always names a policy an earlier quote step created. Nothing
91	  // validates that yet — the test rejecting unknown references will force the
92	  // question of what to do when it is absent.
93	  const covered = state.policies.get(policyIndex) ?? { remainingCap: 0 };
94	  const payout = payoutForDamages(incident.damages);
95	  const remainingCap = covered.remainingCap - payout;
96	
97	  return {
98	    outcome: { payout, remainingCap },
99	    state: withPolicy(state, policyIndex, { remainingCap }),
100	  };
101	};
102	
103	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
104	// so that adding a step kind to the Step union turns "I forgot to handle it"
105	// into a compile error rather than a wrong number.
106	const runStep = (
107	  step: Step,
108	  customer: Customer,
109	  state: ScenarioState,
110	  index: number,
111	): StepRun => {
112	  switch (step.op) {
113	    case "quote":
114	      return runQuote(step, customer, state, index);
115	    case "claim":
116	      return runClaim(step, state);
117	  }
118	};
119	
120	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
121	  const { results } = steps.reduce<{
122	    results: StepOutcome[];
123	    state: ScenarioState;
124	  }>(
125	    ({ results, state }, step, index) => {
126	      const stepRun = runStep(step, customer, state, index);
127	      return { results: [...results, stepRun.outcome], state: stepRun.state };
128	    },
129	    { results: [], state: INITIAL_STATE },
130	  );
131	
132	  return { results };
133	};
