const DEDUCTIBLE_PER_DAMAGE = 100;

// How much of a damage the policy reimburses before the deductible bites.
// Currently always the full amount: no clause yet reimburses a damaged item at
// anything other than face value. The item is in scope because the clauses
// that will change this — the dragon-material and high-enchantment rules —
// read the ITEM, not the damage entry.
const reimbursementFor = (_item: Item, damage: Damage): number =>
  damage.amount;

// The customer bears the first 100 G of each damage entry separately, so two
// damaged swords carry two deductibles rather than one. The deductible comes
// off last, after whatever the reimbursement clauses allow.
const payoutForDamage = (item: Item, damage: Damage): number =>
  reimbursementFor(item, damage) - DEDUCTIBLE_PER_DAMAGE;

// Which insured item a damage entry is about. A damage names its item by type,
// so the first item of that type answers it. That is exact while a policy
// holds at most one item per type; the test rejecting more damage entries of a
// type than the policy covers is what will force a real pairing.
const damagedItem = (items: Item[], damage: Damage): Item | undefined =>
  items.find((item) => item.type === damage.itemType);

export const payoutForDamages = (items: Item[], damages: Damage[]): number =>
  damages.reduce((total, damage) => {
    const item = damagedItem(items, damage);
    return total + (item === undefined ? 0 : payoutForDamage(item, damage));
  }, 0);

interface Policy {
  // The insured items, kept because a claim is settled against them: what a
  // damage reimburses depends on the item's own material and enchantment, not
  // on the damage entry alone.
  items: Item[];
  remainingCap: number;
}

